int linear_search(int array[], int n, int search_key){
    int i = 0;
    int comparisons = 0;
    while(i<n && array[i]!=search_key){
        i++;
        comparisons += 2;
    }
    if(array[i]==search_key){
        return comparisons+1;
    } else{
        // std::cout << "There is no such element in the list.\n";
        return comparisons+1;
    }
}

int sentinel_linear_search(int array[], int n, int search_key){
    int comparisons = 0;
    
    int* new_array = new int[n+1];
    std::copy(array, array + n, new_array);
    new_array[n] = search_key;

    int i = 0;
    while(new_array[i] != search_key){
        i++;
        comparisons ++;
    }
    if (i == n){
        // std::cout << "There is no such element in the list.\n";
        return comparisons+1;
    } else{
        return comparisons+1;
    }
}


