int linear_o_search(int array[], int n, int search_key){
    int comparisons = 0;
    
    int i = 0;
    while(array[i] < search_key && i < n-1){
        comparisons += 2;
        i++;
    }
    
    if (array[i]==search_key){
        return comparisons+1;
    } else{
        // std::cout << "There is no such element in the list.\n";
        return comparisons+1;
    }
}

int improved_linear_o_search(int array[], int n, int search_key){
    int comparisons = 0;

    comparisons++;
    if (array[n-1] < search_key){
        return comparisons;
    }
    
    int i = 0;
    while(array[i] < search_key){
        comparisons++;
    }
    if(array[i] == search_key){
        return comparisons+1;
    } else {
        // std::cout << "There is no such element in the list.\n";
        return comparisons+1;
    }
}

